mapper.sql:
WHERE products.is_active IN (1,2)

  AND (
     products.name LIKE CONCAT("%", #{filter.searchText}, "%")
  OR products.barcode LIKE CONCAT("%", #{filter.searchText}, "%")
  OR products.code LIKE CONCAT("%", #{filter.searchText}, "%")
  )


  AND products.is_packet = #{filter.show}


  AND products.is_active = #{filter.isActive}


  AND products.id IN (SELECT product_id FROM product_pgroups WHERE pgroup_id = #{filter.groupId})


  AND products.barcode = #{filter.upc}


  AND products.code = #{filter.sku}


  AND products.created_by = #{userId}

mapper.select:
SELECT



ORDER BY


    ${filter.orderBy}


    products.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM products
WHERE is_active = 1 AND barcode = #{name}
 AND id != #{id}

