mapper.update:
UPDATE product_stock_levels
SET is_active = 2,
    modified = NOW(),
    modified_by = #{userId}
WHERE product_id = #{productId}
  AND is_active = 1

UPDATE products SET
  is_active = -1,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id};

UPDATE products SET
  is_active = #{status.isActive},
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{status.id};
